import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for DoubleSerializer.serializeWithType
 */
public class DoubleSerializer_serializeWithType_TriageGen0Test {

    private NumberSerializers.DoubleSerializer doubleSerializer;
    private JsonGenerator jsonGenerator;
    private SerializerProvider serializerProvider;
    private TypeSerializer typeSerializer;

    @Before
    public void setUp() {
        // We use a spy because serializeWithType calls the local serialize method.
        // To verify that serializeWithType correctly delegates to serialize, 
        // we need to spy on the instance under test.
        doubleSerializer = spy(new NumberSerializers.DoubleSerializer());
        jsonGenerator = Mockito.mock(JsonGenerator.class);
        serializerProvider = Mockito.mock(SerializerProvider.class);
        typeSerializer = Mockito.mock(TypeSerializer.class);
    }

    @Test
    public void testSerializeWithType_Success() throws IOException {
        Object value = 123.45;

        // Mock the internal serialize call to do nothing
        doNothing().when(doubleSerializer).serialize(eq(value), eq(jsonGenerator), eq(serializerProvider));

        // Execute
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Verify that serialize was called with the correct parameters (ignoring typeSer as per implementation)
        verify(doubleSerializer).serialize(value, jsonGenerator, serializerProvider);
    }

    @Test(expected = IOException.class)
    public void testSerializeWithType_ThrowsIOException() throws IOException {
        Object value = 123.45;

        // Mock the internal serialize call to throw an IOException
        doThrow(new IOException("Simulated IO error")).when(doubleSerializer)
                .serialize(eq(value), eq(jsonGenerator), eq(serializerProvider));

        // Execute
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);
    }

    @Test
    public void testSerializeWithType_WithNullValue() throws IOException {
        Object value = null;

        // Mock the internal serialize call to handle null
        doNothing().when(doubleSerializer).serialize(eq(null), eq(jsonGenerator), eq(serializerProvider));

        // Execute
        doubleSerializer.serializeWithType(value, jsonGenerator, serializerProvider, typeSerializer);

        // Verify delegation
        verify(doubleSerializer).serialize(null, jsonGenerator, serializerProvider);
    }
}
